CREATE VIRTUAL TABLE t1 USING fts4(x, y); WITH RECURSIVE n(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM n WHERE i<5000) INSERT INTO t1(docid, x, y) SELECT i, printf('alpha token%05d', i), printf('beta group%d', i%17) FROM n; CREATE VIRTUAL TABLE t3 USING fts4(x, y, prefix="2,3", languageid=langid); INSERT INTO t3(docid, x, y, langid) SELECT docid, x, y, (docid%9)*4 FROM t1 ORDER BY docid;